-- One-time test load: 3 users, 2 partners, 3 applications, and Developer access.
-- Replace EMAIL1/EMAIL2/EMAIL3 in a private copy. Department 2222 must already exist.
-- Requires the migrated portal schema and existing Partner Developer role/policies.
-- Run: psql -X -d YOUR_DATABASE -f load_test_data.sql (commits the data).
-- Existing emails or UUIDs cause an error; this script does not update or reuse rows.
\set ON_ERROR_STOP on

BEGIN;

-- 1. Users. Integer IDs are generated by PostgreSQL; onboarding fields stay unset.
INSERT INTO public."user" (
  uuid, email, username, name, profile_image_url, created_at,
  is_deleted, is_superuser, enabled
)
SELECT user_uuid::uuid, email, email, name, 'https://profileimageurl.com', CURRENT_TIMESTAMP,
  false, false, false
FROM (VALUES
  ('10432000-0000-4000-8000-000000000001', 'test1', 'Test User 1'),
  ('10432000-0000-4000-8000-000000000002', 'test2', 'Test User 2'),
  ('10432000-0000-4000-8000-000000000003', 'test', 'Test User 3')
) AS test_user(user_uuid, email, name);

-- 2. Partners. Resolve the department's integer ID from its catalog number.
INSERT INTO public.partner_group (uuid, department_id, name_en, name_fr, created_at, is_deleted)
SELECT partner_uuid::uuid,
  (SELECT id FROM public.department WHERE gc_org_id = 2222 AND NOT is_deleted AND deleted_at IS NULL),
  name_en, name_fr, CURRENT_TIMESTAMP, false
FROM (VALUES
  ('10430000-0000-4000-8000-000000000001', 'QA Partner One', 'Partenaire de test un'),
  ('10430000-0000-4000-8000-000000000002', 'QA Partner Two', 'Partenaire de test deux')
) AS test_partner(partner_uuid, name_en, name_fr);

-- 3. Applications: one for Partner One, two for Partner Two.
INSERT INTO public.application (uuid, partner_group_id, name_en, name_fr, created_at, is_deleted)
SELECT application_uuid::uuid,
  (SELECT id FROM public.partner_group WHERE uuid = partner_uuid::uuid),
  name_en, name_fr, CURRENT_TIMESTAMP, false
FROM (VALUES
  ('10431000-0000-4000-8000-000000000001', '10430000-0000-4000-8000-000000000001', 'QA App One', 'Application de test un'),
  ('10431000-0000-4000-8000-000000000002', '10430000-0000-4000-8000-000000000002', 'QA App Two', 'Application de test deux'),
  ('10431000-0000-4000-8000-000000000003', '10430000-0000-4000-8000-000000000002', 'QA App Three', 'Application de test trois')
) AS test_application(application_uuid, partner_uuid, name_en, name_fr);

-- Stop before granting access if placeholders remain or the shared role reaches other partners.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public."user"
    WHERE uuid IN ('10432000-0000-4000-8000-000000000001',
                   '10432000-0000-4000-8000-000000000002',
                   '10432000-0000-4000-8000-000000000003')
      AND (email <> lower(btrim(email)) OR email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$')
  ) THEN
    RAISE EXCEPTION 'Replace EMAIL1, EMAIL2 and EMAIL3 with the lowercase test emails before running.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.partner_group_role AS role_link
    JOIN public.role AS role ON role.id = role_link.role_id
    JOIN public.partner_group AS partner ON partner.id = role_link.partner_group_id
    WHERE role.name = 'Partner Developer' AND NOT role.is_deleted
      AND NOT role_link.is_deleted AND NOT partner.is_deleted
  ) THEN
    RAISE EXCEPTION 'Partner Developer already has partner access. Use a clean test dataset for this seed.';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.access_policy
    WHERE subject = 'Partner Developer' AND resource = 'applications'
      AND action IN ('read', 'write') AND NOT is_deleted
    HAVING count(*) = 2 AND count(DISTINCT action) = 2 AND bool_and(deleted_at IS NULL)
  ) THEN
    RAISE EXCEPTION 'The existing Developer applications/read and applications/write policies are required.';
  END IF;
END;
$$;

-- 4. Link both partners to Developer. Every existing Developer also receives this scope.
INSERT INTO public.partner_group_role (partner_group_id, role_id, uuid, created_at, is_deleted)
SELECT (SELECT id FROM public.partner_group WHERE uuid = partner_uuid::uuid),
  (SELECT id FROM public.role WHERE name = 'Partner Developer' AND NOT is_deleted AND deleted_at IS NULL),
  gen_random_uuid(), CURRENT_TIMESTAMP, false
FROM (VALUES
  ('10430000-0000-4000-8000-000000000001'),
  ('10430000-0000-4000-8000-000000000002')
) AS test_partner(partner_uuid);

-- 5. Give EMAIL2 and EMAIL3 Developer access. EMAIL1 has no roles.
INSERT INTO public.user_role (user_id, role_id, uuid, created_at, is_deleted)
SELECT (SELECT id FROM public."user" WHERE uuid = user_uuid::uuid),
  (SELECT id FROM public.role WHERE name = 'Partner Developer' AND NOT is_deleted AND deleted_at IS NULL),
  gen_random_uuid(), CURRENT_TIMESTAMP, false
FROM (VALUES
  ('10432000-0000-4000-8000-000000000002'),
  ('10432000-0000-4000-8000-000000000003')
) AS test_user(user_uuid);

COMMIT;
